import { Recipe, ShoppingCategory } from '../types';

function cat(n: string): ShoppingCategory {
  const s = n.toLowerCase();
  if (/poulet|dinde|agneau|viande|jambon|bacon|lardons|chorizo|prosciutto|boeuf|bœuf|kefta/.test(s)) return 'Viandes';
  if (/saumon|thon|crevette|sardine|cabillaud|anchois|hareng|maquereau/.test(s)) return 'Poissons';
  if (/\blait\b|cr[eè]me|fromage|yaourt|skyr|beurre|\boeuf|\bœuf|mozza|feta|ricotta|gorgonzola|ch[eè]vre|parmesan|camembert|mascarpone|emmental|cheddar|burrata|halloumi|kiri/.test(s)) return 'Produits laitiers & Œufs';
  if (/farine|chapelure|\briz\b|semoule|quinoa|vermicelles|lasagne|nouilles|naan|\bpain\b|levure|\bwrap\b|gnocchi|p[aâ]tes|tortilla/.test(s)) return 'Boulangerie';
  if (/carotte|courgette|tomate|butternut|oignon|[eé]pinard|concombre|patate|pomme|haricot|lentille|ma[iï]s|champignon|aubergine|poivron|basilic|coriandre|persil|menthe|thym|romarin|gingembre|citron|ananas|fraise|framboise|banane|[eé]chalote|pistache|noix|amande|noisette|avocat|mangue/.test(s)) return 'Fruits & Légumes';
  return 'Épicerie';
}

function em(name: string, meal: string): string {
  const n = name.toLowerCase();
  if (/soupe|velout/.test(n)) return '🍲';
  if (/salade/.test(n)) return '🥗';
  if (/risotto/.test(n)) return '🍚';
  if (/p[aâ]tes|pasta/.test(n)) return '🍝';
  if (/pizza/.test(n)) return '🍕';
  if (/tarte|quiche|flan/.test(n)) return '🥧';
  if (/wrap|sandwich|croque|toast/.test(n)) return '🥪';
  if (/poulet|chicken/.test(n)) return '🍗';
  if (/saumon|thon|poisson|crevette|sardine/.test(n)) return '🐟';
  if (/gnocchi/.test(n)) return '🥔';
  if (/\briz\b/.test(n)) return '🍚';
  if (/burger|bun/.test(n)) return '🍔';
  if (/cr[eê]pe|pancake|gaufre/.test(n)) return '🥞';
  if (/curry/.test(n)) return '🍛';
  if (/oeuf|[oœ]uf|omelette/.test(n)) return '🥚';
  if (/chips|frites/.test(n)) return '🍟';
  if (/cookie/.test(n)) return '🍪';
  if (/muffin/.test(n)) return '🧁';
  if (/brownie|brookie/.test(n)) return '🍫';
  if (/chocolat/.test(n)) return '🍫';
  if (/glace|magnum|sorbet/.test(n)) return '🍦';
  if (/g[aâ]teau|cake/.test(n)) return '🎂';
  if (/biscuit|oreo/.test(n)) return '🍪';
  if (/mousse|tiramisu/.test(n)) return '🍮';
  if (/crumble/.test(n)) return '🥣';
  if (/barre|snickers|twix/.test(n)) return '🍫';
  if (/smoothie|jus|infusion|sirop/.test(n)) return '🥤';
  if (/caf[eé]|latte/.test(n)) return '☕';
  if (/donut|bagel/.test(n)) return '🍩';
  if (/tacos|nems|gyoza/.test(n)) return '🥟';
  if (/boulette|kefta/.test(n)) return '🧆';
  if (/rillette|houmous/.test(n)) return '🫙';
  if (meal === 'breakfast') return '☕';
  return '🍽️';
}

